// Run with: node --test (from extension/)
//
// The extension rebuilds the API's features and runs the model itself, so it
// must give the same answers as the Python code. tests/fixtures/
// extension_parity.json is generated by scripts/make_parity_fixture.py from
// app/services/features.py and the committed model; this checks the port
// against it.
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const core = require("./core.js");

const ROOT = path.join(__dirname, "..");
const readJson = (...parts) => JSON.parse(fs.readFileSync(path.join(ROOT, ...parts), "utf8"));

const model = readJson("models", "model.json");
const fixture = readJson("tests", "fixtures", "extension_parity.json");

const clone = (value) => JSON.parse(JSON.stringify(value));

test("the committed model.json is one this extension can run", () => {
  assert.doesNotThrow(() => core.validateModel(model));
});

for (const c of fixture.cases) {
  test(`matches the Python path: ${c.name}`, () => {
    const result = core.predictContest(model, {
      history: c.history,
      currentRating: c.current_rating,
      contest: c.contest,
      rank: c.rank,
    });
    const expected = c.expected;

    assert.equal(result.features.length, expected.features.length);
    result.features.forEach((value, i) => {
      assert.ok(
        Math.abs(value - expected.features[i]) <= 1e-9,
        `feature ${i} (${core.FEATURE_NAMES[i]}): ${value} vs ${expected.features[i]}`,
      );
    });
    assert.equal(result.before, expected.rating_before);
    assert.ok(
      Math.abs(result.delta - expected.prediction) <= 1e-3,
      `prediction ${result.delta} vs ${expected.prediction}`,
    );
    assert.equal(result.after, result.before + result.delta);
    if (expected.actual_change === null) {
      assert.equal(result.actual, null);
    } else {
      assert.ok(Math.abs(result.actual - expected.actual_change) <= 1e-9);
    }
  });
}

test("rejects a model built for other inputs", () => {
  const wrongVersion = clone(model);
  wrongVersion.feature_version = core.FEATURE_VERSION + 1;
  assert.throws(() => core.validateModel(wrongVersion), /feature_version/);

  const wrongWidth = clone(model);
  wrongWidth.input_dim = 14;
  assert.throws(() => core.validateModel(wrongWidth), /input_dim/);

  const wrongActivation = clone(model);
  wrongActivation.layers[0].activation = "tanh";
  assert.throws(() => core.validateModel(wrongActivation), /activation/);

  const reordered = clone(model);
  [reordered.features[0], reordered.features[1]] = [reordered.features[1], reordered.features[0]];
  assert.throws(() => core.validateModel(reordered), /features/);

  const brokenShape = clone(model);
  brokenShape.layers[1].kernel.pop();
  assert.throws(() => core.validateModel(brokenShape), /kernel/);
});

test("refuses an implausible prediction like the API does", () => {
  const huge = clone(model);
  const last = huge.layers[huge.layers.length - 1];
  last.bias[0] = 10000;
  assert.throws(
    () =>
      core.predictContest(huge, {
        history: [],
        currentRating: 1500,
        contest: "weekly-contest-530",
        rank: 100,
      }),
    /implausible/,
  );
});
